func Run(ctx context.Context, opts Options, args []string) error {
	if opts.Version == "" {
		opts.Version = "dev"
	}
	if opts.Stdout == nil {
		opts.Stdout = io.Discard
	}
	if opts.Stderr == nil {
		opts.Stderr = io.Discard
	}

	if len(args) == 0 {
		printHelp(opts.Stdout)
		return nil
	}

	// Per-command help: `entire graph <cmd> --help` prints that command's detail
	// view and exits, without touching each runX. Only fires for commands that
	// have a doc entry — which includes `help` itself, so `help --help` prints
	// help's own detail view rather than the root listing. A bare `--help` has
	// no command word and is handled above.
	if doc, ok := findCommandDoc(args[0]); ok && wantsHelp(doc, args[1:]) {
		renderCommandHelp(opts.Stdout, args[0])
		return nil
	}

	switch args[0] {
	case "diff":
		return runDiff(ctx, opts, args[1:])
	case "commit":
		return runCommit(ctx, opts, args[1:])
	case "checkpoint":
		return runCheckpoint(ctx, opts, args[1:])
	case "analyze":
		return runAnalyze(ctx, opts, args[1:])
	case "doctor":
		return runDoctor(ctx, opts, args[1:])
	case "capabilities":
		return runCapabilities(opts, args[1:])
	case "snapshot":
		return runProviderRecords(ctx, opts, args[1:], "snapshot")
	case "snapshot-query":
		return runSnapshotQuery(opts, args[1:])
	case "symbols":
		return runProviderRecords(ctx, opts, args[1:], "symbols")
	case "edges":
		return runProviderRecords(ctx, opts, args[1:], "edges")
	case "search":
		return runSearch(ctx, opts, args[1:])
	case "index":
		return runIndex(ctx, opts, args[1:])
	case "def":
		return runDef(ctx, opts, args[1:])
	case "explain":
		return runExplain(ctx, opts, args[1:])
	case "neighbors":
		return runNeighbors(ctx, opts, args[1:])
	case "impact":
		return runImpact(ctx, opts, args[1:])
	case "verify":
		return runVerify(ctx, opts, args[1:])
	case "stats":
		return runStats(ctx, opts, args[1:])
	case "agent-guide":
		return runAgentGuide(opts, args[1:])
	case "init-agents":
		return runInitAgents(opts, args[1:])
	case "version", "--version", "-v":
		if len(args) > 1 && args[1] == "--json" {
			return json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout)).Encode(map[string]string{
				"provider":          sem.ProviderName,
				"version":           opts.Version,
				"identity_revision": sem.IdentityRevision,
package cli

import (
	"fmt"
	"io"
	"strings"
)

// This file is the single source of truth for `entire graph` help. The CLI is a
// hand-rolled dispatcher (see root.go), so instead of a framework we keep a small
// registry of commandDoc values and render both the grouped root listing and the
// per-command detail view from it. Adding a command here (and to the Run switch)
// is what makes it show up in help and answer `--help`.

// cmdGroup buckets commands in the root listing by what the user is trying to do.
type cmdGroup int

const (
	groupSetup   cmdGroup = iota // set up the graph with a coding agent
	groupInspect                 // query the graph to locate/understand code
	groupAnalyze                 // change/risk analysis and reporting
	groupMeta                    // help, diagnostics, and version info
)

// groupTitles are the section headers, rendered in this order.
var groupOrder = []cmdGroup{groupSetup, groupInspect, groupAnalyze, groupMeta}

var groupTitles = map[cmdGroup]string{
	groupSetup:   "Set up your agent",
	groupInspect: "Inspect the graph",
	groupAnalyze: "Analyze changes & more",
	groupMeta:    "Help & diagnostics",
}

type flagDoc struct {
	name string // e.g. "--top-k"
	arg  string // value placeholder, empty for boolean flags, e.g. "n"
	def  string // default value shown as "(default: X)", empty to omit
	desc string
}

type argDoc struct {
	name string // e.g. "<checkpoint-id>"
	desc string
}

type commandDoc struct {
	name     string
	group    cmdGroup
	summary  string   // one line, shown in the root listing
	usage    []string // one or more usage lines
	long     string   // detail paragraph(s) shown under Usage
	args     []argDoc
	flags    []flagDoc
	examples []string
