package cli

import (
 "bytes"
 "strings"
 "testing"
)

func TestQueryAndSearchCompatibility(t *testing.T) {
 repo := t.TempDir()
 write(t, repo, "auth.py", "def validate_token(token):\n    return bool(token)\n")
 var canonical string
 for _, command := range []string{"query", "search"} {
  var out bytes.Buffer
  err := Run(t.Context(), Options{Env: EntireEnv{RepoRoot: repo}, Stdout: &out}, []string{
   command, "--repo", repo, "--query", "validate_token", "--format", "text", "--profile", "syntax-only", "--index-all-files",
  })
  if err != nil { t.Fatal(err) }
  if !strings.Contains(out.String(), "auth.py:1") { t.Fatalf("%s did not return the definition: %s", command, &out) }
  if command == "query" { canonical = out.String() } else if out.String() != canonical { t.Fatalf("search alias output differs from query:\n%s", &out) }
  if err := checkPreflight("dev", command + " --query validate_token --format text"); err != nil { t.Fatal(err) }
  if verb, ok := graphVerbFromCommand("entire graph " + command + " --query validate_token"); !ok || !graphLocateVerbs[verb] { t.Fatalf("%s is not counted as a locate call", command) }
 }
}

func TestQueryHelpHidesSearchAlias(t *testing.T) {
 var root bytes.Buffer
 renderRootHelp(&root)
 if !strings.Contains(root.String(), "  query ") || strings.Contains(root.String(), "  search ") { t.Fatalf("unexpected command listing:\n%s", &root) }
 for _, args := range [][]string{{"query", "--help"}, {"search", "--help"}, {"help", "search"}} {
  var out bytes.Buffer
  if err := Run(t.Context(), Options{Stdout: &out}, args); err != nil { t.Fatal(err) }
  if !strings.Contains(out.String(), "entire graph query --query") || strings.Contains(out.String(), "entire graph search") { t.Fatalf("unexpected help for %v:\n%s", args, &out) }
 }
}
